export function evaluate({ inputs, time }) {
 const g = 9.8, u = inputs.launchSpeed;
 const T = 2 * u / g, ta = u / g;
 const t = Math.max(0, Math.min(T, time));
 const h = u * t - g * t * t / 2;
 const v = u - g * t;
 const apexH = u * u / (2 * g);
 const eps = 0.005;
 const top = Math.abs(t - ta) < eps;
 const state = top ? 'Still for an instant' : (t < ta ? 'Moving up' : 'Moving down');
 const base = 380, scale = 300 / 1.3;
 const by = base - h * scale;
 const bx = 260;
 const objs = [];
 objs.push(...sdk.panel({ id: 'lane.toss', x: 20, y: 40, w: 600, h: 360, title: 'Tossed ball', state: state }));
 objs.push(sdk.axis('axis.h', { x: 100, y: base, length: 320, orientation: 'y', min: 0, max: 1.3, ticks: [0, 0.5, 1], label: 'Height', unit: 'm' }));
 objs.push(sdk.line('guide.launch', 110, base, 420, base, { role: 'neutral' }));
 objs.push(sdk.circle('ball.toss', bx, by - 14, 28, { role: 'output' }));
 objs.push(...sdk.vector('vec.v', { x: bx + 40, y: by - 14 }, { value: Math.abs(v) < 0.05 ? 0 : v, direction: 'up' }, { scale: 14, minLength: 12, label: 'v', role: 'input' }));
 objs.push(...sdk.vector('vec.a', { x: bx - 40, y: by - 14 }, { value: -g, direction: 'up' }, { scale: 6, label: 'a', role: 'warning' }));
 objs.push(...sdk.callout(bx + 110, 120, [state, 'Gravity pulls down'], { id: 'callout.toss' }));
 return {
 frame: { width: 640, height: 420, objects: objs, readouts: [{ id: 'motionState', value: state }, { id: 'gravityState', value: 'Gravity pulls down' }] },
 quantities: { launchSpeed: u, gravity: g, apexTime: ta, apexHeight: apexH, velocity: v, height: h }
 };
}
